#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include "cJSON.h"
#include "lodepng.h"

static std::string read_file(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::string s;
    s.resize(n);
    if (fread(&s[0], 1, n, f) != (size_t)n) { fclose(f); exit(1); }
    fclose(f);
    return s;
}

// Load a 2D array [rows][cols] from a cJSON array of arrays.
static std::vector<std::vector<double>> load2d(cJSON* obj, const char* key) {
    cJSON* a = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!a || !cJSON_IsArray(a)) { fprintf(stderr, "missing %s\n", key); exit(1); }
    std::vector<std::vector<double>> out;
    int rows = cJSON_GetArraySize(a);
    for (int i = 0; i < rows; i++) {
        cJSON* row = cJSON_GetArrayItem(a, i);
        std::vector<double> r;
        int cols = cJSON_GetArraySize(row);
        for (int j = 0; j < cols; j++)
            r.push_back(cJSON_GetArrayItem(row, j)->valuedouble);
        out.push_back(std::move(r));
    }
    return out;
}

static std::vector<double> load1d(cJSON* obj, const char* key) {
    cJSON* a = cJSON_GetObjectItemCaseSensitive(obj, key);
    if (!a || !cJSON_IsArray(a)) { fprintf(stderr, "missing %s\n", key); exit(1); }
    std::vector<double> out;
    int n = cJSON_GetArraySize(a);
    for (int i = 0; i < n; i++)
        out.push_back(cJSON_GetArrayItem(a, i)->valuedouble);
    return out;
}

// y = relu?(W * x + b), W is [out][in]
static std::vector<double> linear(const std::vector<std::vector<double>>& W,
                                  const std::vector<double>& b,
                                  const std::vector<double>& x,
                                  bool relu) {
    std::vector<double> y(W.size());
    for (size_t o = 0; o < W.size(); o++) {
        double s = b[o];
        const std::vector<double>& wr = W[o];
        for (size_t i = 0; i < wr.size(); i++) s += wr[i] * x[i];
        if (relu && s < 0) s = 0;
        y[o] = s;
    }
    return y;
}

int main(int argc, char** argv) {
    if (argc < 3) { fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]); return 1; }

    std::string wj = read_file(argv[1]);
    cJSON* root = cJSON_Parse(wj.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    auto W1 = load2d(root, "input_layer.weight");
    auto b1 = load1d(root, "input_layer.bias");
    auto W2 = load2d(root, "hidden_layer.weight");
    auto b2 = load1d(root, "hidden_layer.bias");
    auto W3 = load2d(root, "output_layer.weight");
    auto b3 = load1d(root, "output_layer.bias");

    std::vector<unsigned char> img;
    unsigned w, h;
    unsigned err = lodepng::decode(img, w, h, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png error: %s\n", lodepng_error_text(err)); return 1; }

    std::vector<double> x(w * h);
    for (size_t i = 0; i < x.size(); i++) x[i] = img[i] / 255.0;

    auto a1 = linear(W1, b1, x, true);
    auto a2 = linear(W2, b2, a1, true);
    auto out = linear(W3, b3, a2, false);

    int best = 0;
    for (size_t i = 1; i < out.size(); i++)
        if (out[i] > out[best]) best = (int)i;

    printf("%d\n", best);

    cJSON_Delete(root);
    return 0;
}
